function _splitCsvList(value){return String(value||'').split(',').map(v=>String(v||'').trim()).filter(Boolean);}
function _addRosterEntry(map,name,category,aliases,teams){const cleanName=String(name||'').trim(); const cleanCategory=String(category||'').trim(); const cleanAliases=(Array.isArray(aliases)?aliases:[]).map(v=>String(v||'').trim()).filter(Boolean); const cleanTeams=(Array.isArray(teams)?teams:[]).map(v=>String(v||'').trim()).filter(Boolean); if(!cleanName||!cleanCategory)return; const entry={name:cleanName,category:cleanCategory,aliases:cleanAliases,teams:cleanTeams}; [cleanName].concat(cleanAliases).forEach((token)=>{const key=String(token||'').trim().toLowerCase(); if(key)map.set(key,entry);});}
