function jumpToRoute(route){const target=String(route||'').trim(); if(!target)return; trackWrestlingPeopleEvent('wrestling_match_open',{entity_type:'match',entity_id:target,entity_label:target,meta:{from_person:String(view&&view.person||'').trim(),route:target}}); try{window.history.pushState({},'',target+(window.location.search||''));}catch(_){} try{window.WrestlingArchive&&window.WrestlingArchive.setMode&&window.WrestlingArchive.setMode('shows',{replace:true,preservePath:true});}catch(_){} }
  function findPersonBySlug(slug){const clean=slugPerson(slug); let match=''; peopleMap.forEach(e=>{if(!match&&e&&e.slug===clean)match=e.person;}); return match;}
  function ensureLightbox(){if(lbEl&&lbImg)return; const el=document.createElement('div'); el.className='waPeopleLightbox'; el.innerHTML='<div class="waPeopleLightboxInner" role="dialog" aria-modal="true" aria-label="Tagged performer shots"><div class="waPeopleLightboxTop"><button type="button" class="waPeopleJump" data-peoplelb="close">Close</button></div><div class="waPeopleLightboxStage"><img class="waPeopleLightboxImg" id="waPeopleLightboxImg" alt="" /></div><div class="waPeopleLightboxStrip" id="waPeopleLightboxStrip"></div></div>'; document.body.appendChild(el); lbEl=el; lbImg=el.querySelector('#waPeopleLightboxImg'); el.addEventListener('click',ev=>{const tgt=ev.target, btn=tgt&&tgt.closest?tgt.closest('[data-peoplelb]'):null; if(btn){const act=String(btn.getAttribute('data-peoplelb')||'').trim(); if(act==='close'){el.classList.remove('is-open'); try{document.body.style.overflow='';}catch(_){} return;} if(act==='thumb'){showLightboxImage(Number(btn.getAttribute('data-idx')||0)); return;}} if(tgt===el){el.classList.remove('is-open'); try{document.body.style.overflow='';}catch(_){} }}); window.addEventListener('keydown',ev=>{if(!lbEl||!lbEl.classList.contains('is-open'))return; if(ev.key==='Escape'){ev.preventDefault(); lbEl.classList.remove('is-open'); try{document.body.style.overflow='';}catch(_){} } if(ev.key==='ArrowLeft'){ev.preventDefault(); showLightboxImage(lbIndex-1);} if(ev.key==='ArrowRight'){ev.preventDefault(); showLightboxImage(lbIndex+1);} });}
  function showLightboxImage(nextIndex){if(!lbEl||!lbImg)return; const list=Array.isArray(lbList)?lbList:[]; if(!list.length)return; const idx=nextIndex<0?(list.length-1):(nextIndex>=list.length?0:nextIndex); lbIndex=idx; const item=list[idx]||{}; const full=String(item.fullUrl||(fullUrlByKey.get(String(item.imageKey||'').trim())||item.thumbUrl||'')).trim(); lbImg.src=full; const strip=lbEl.querySelector('#waPeopleLightboxStrip'); if(strip){Array.from(strip.querySelectorAll('.waPeopleLightboxThumb')).forEach((thumbEl,thumbIdx)=>thumbEl.classList.toggle('active',thumbIdx===idx)); const active=strip.querySelector('.waPeopleLightboxThumb.active'); if(active&&active.scrollIntoView)active.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});} }
  function openLightbox(list,index){ensureLightbox(); lbList=Array.isArray(list)?list:[]; lbIndex=Math.max(0,Number(index||0)); if(!lbEl)return; const strip=lbEl.querySelector('#waPeopleLightboxStrip'); if(strip){strip.innerHTML=lbList.map((item,idx)=>`<button type="button" class="waPeopleLightboxThumb${idx===lbIndex?' active':''}" data-peoplelb="thumb" data-idx="${idx}"><img src="${eh(String(item.thumbUrl||item.fullUrl||'').trim())}" alt="Thumbnail ${idx+1}" loading="lazy" decoding="async" /></button>`).join('');} lbEl.classList.add('is-open'); try{document.body.style.overflow='hidden';}catch(_){} showLightboxImage(lbIndex); }
  function collapseShotPanels(exceptRoute){if(!root)return; Array.from(root.querySelectorAll('[data-shot-panel]')).forEach((panelEl)=>{const route=String(panelEl.getAttribute('data-shot-panel')||'').trim(); if(exceptRoute&&route===exceptRoute)return; panelEl.style.display='none';}); Array.from(root.querySelectorAll('[data-appearance-route]')).forEach((cardEl)=>{const route=String(cardEl.getAttribute('data-appearance-route')||'').trim(); const open=!!(exceptRoute&&route===exceptRoute); cardEl.classList.toggle('is-open',open); cardEl.setAttribute('aria-expanded', open?'true':'false');});}
  function renderTaggedShotsPanel(route,shots){if(!root)return; const cleanRoute=String(route||'').trim(); const p=root.querySelector(`[data-shot-panel="${esc(cleanRoute)}"]`); if(!p)return; const list=Array.isArray(shots)?shots:[]; if(!list.length){p.innerHTML=`<div class="waPeopleShotHeader"><div class="waPeopleShotHeaderCopy"><div class="waPeopleShotStatus">0 tagged shots</div><div class="waPeopleShotHint">Caption match</div></div></div><div class="waPeopleShotEmpty">No caption matches were found for ${eh(view.person)} in this album. This pass only reads the photo caption field.</div>`; return;} const expanded=expandedShotPanels.has(cleanRoute); const previewCount=8; const visible=expanded?list:list.slice(0,previewCount); p.innerHTML=`<div class="waPeopleShotHeader"><div class="waPeopleShotHeaderCopy"><div class="waPeopleShotStatus">${eh(String(list.length))} tagged shots</div><div class="waPeopleShotHint">Caption match</div></div>${list.length>previewCount?`<button type="button" class="waPeopleJump is-secondary" data-show-all="${eh(cleanRoute)}" aria-expanded="${expanded?'true':'false'}">${expanded?'Show less':'Show all'}</button>`:''}</div><div class="waPeopleShotGrid">${visible.map((shot,idx)=>`<button type="button" class="waPeopleShotThumb" data-shot-open="${eh(cleanRoute)}" data-shot-index="${idx}" aria-label="Open tagged shot ${idx+1}"><img src="${eh(String(shot.thumbUrl||shot.fullUrl||'').trim())}" alt="Tagged shot ${idx+1}" loading="lazy" decoding="async" /><span class="waPeopleShotThumbIndex">#${idx+1}</span></button>`).join('')}</div>`; }
  async function loadTaggedShotsForRoute(route){if(!root||!view||view.mode!=='person')return; const cleanRoute=String(route||'').trim(); const p=root.querySelector(`[data-shot-panel="${esc(cleanRoute)}"]`); const card=root.querySelector(`[data-appearance-route="${esc(cleanRoute)}"]`); if(!p)return; const isOpen=p.style.display!==''?false:true; if(isOpen&&String(p.dataset.loading||'')!=='1'){collapseShotPanels(''); return;} collapseShotPanels(cleanRoute); const entry=peopleMap.get(String(view.person||'').toLowerCase()); const app=entry&&Array.isArray(entry.appearances)?entry.appearances.find(item=>String(item.route||'').trim()===cleanRoute):null; if(!app)return; p.style.display=''; if(card){card.classList.add('is-open');card.setAttribute('aria-expanded','true');} if(String(p.dataset.loaded||'')==='1'){renderTaggedShotsPanel(cleanRoute,shotCache.get(`${cleanRoute}|${String(view.person||'').trim().toLowerCase()}`)||[]); return;} p.dataset.loading='1'; p.innerHTML='<div class="waPeopleShotStatus">Reading caption-tagged shots...</div>'; const shots=await shotsForAppearance(app,view.person); p.dataset.loading='0'; p.dataset.loaded='1'; renderTaggedShotsPanel(cleanRoute,shots); }
  function bindEvents(){if(!root||root._waPeopleBound)return; root._waPeopleBound=true; root.addEventListener('click',e=>{const target=e.target; const letterBtn=target&&target.closest?target.closest('[data-letter]'):null; if(letterBtn){const raw=String(letterBtn.getAttribute('data-letter')||'').trim().toUpperCase(); activeLetter=(!raw||raw==='ALL')?null:raw; renderCurrent(); return;} const catToggle=target&&target.closest?target.closest('[data-category-toggle]'):null; if(catToggle){const cat=String(catToggle.getAttribute('data-category-toggle')||'').trim(); if(cat){if(collapsedCategories.has(cat))collapsedCategories.delete(cat); else collapsedCategories.add(cat); renderList();} return;} const personCard=target&&target.closest?target.closest('[data-person]'):null; if(personCard){openPerson(personCard.getAttribute('data-person')); return;} const backBtn=target&&target.closest?target.closest('[data-action="back"]'):null; if(backBtn){backToList(); return;} const routeBtn=target&&target.closest?target.closest('[data-route]'):null; if(routeBtn){jumpToRoute(routeBtn.getAttribute('data-route')); return;} const showAllBtn=target&&target.closest?target.closest('[data-show-all]'):null; if(showAllBtn){const route=String(showAllBtn.getAttribute('data-show-all')||'').trim(); if(route){if(expandedShotPanels.has(route))expandedShotPanels.delete(route); else expandedShotPanels.add(route); const cacheKey=`${route}|${String((view&&view.person)||'').trim().toLowerCase()}`; renderTaggedShotsPanel(route,shotCache.get(cacheKey)||[]);} return;} const shotBtn=target&&target.closest?target.closest('[data-shot-open]'):null; if(shotBtn){const route=String(shotBtn.getAttribute('data-shot-open')||'').trim(); const idx=Number(shotBtn.getAttribute('data-shot-index')||0); const cacheKey=`${route}|${String((view&&view.person)||'').trim().toLowerCase()}`; const shots=shotCache.get(cacheKey)||[]; if(shots.length)openLightbox(shots,idx); return;} const shotPanel=target&&target.closest?target.closest('[data-shot-panel]'):null; if(shotPanel)return; const appearanceCard=target&&target.closest?target.closest('[data-appearance-route]'):null; if(appearanceCard){loadTaggedShotsForRoute(appearanceCard.getAttribute('data-appearance-route')); return;} });}
  async function onMount(panelEl){ensureStyles(); panel=panelEl||document.getElementById('wrestlingContentPanel')||document.body; const token=++mountToken; root=panel.querySelector('#waPeopleRoot'); if(!root){panel.innerHTML=render(); root=panel.querySelector('#waPeopleRoot');} bindEvents(); try{_wakeBackendOnce();}catch(_){} rosterMap=await loadRosterMap().catch(()=>new Map()); shows=await loadShows().catch(()=>[]); peopleMap=enrichPeopleMap(await loadPeopleIndexData().catch(()=>new Map()),buildShowLookup(shows)); if(token!==mountToken)return; try{const bp=root.querySelector('#waPeopleBootPanel'); if(bp&&bp.parentNode)bp.parentNode.removeChild(bp);}catch(_){} const parts=String(window.location.pathname||'').trim().replace(/^\/+|\/+$/g,'').split('/').filter(Boolean); const slug=(String(parts[0]||'').toLowerCase()==='wrestling'&&String(parts[1]||'').toLowerCase()==='people')?slugPerson(parts[2]||''):''; if(slug){const personName=findPersonBySlug(slug); view=personName?{mode:'person',person:personName}:{mode:'list',person:''};}else view={mode:'list',person:''}; renderCurrent(); }
  function destroy(){shows=[]; peopleMap=new Map(); panel=null; root=null; view={mode:'list',person:''}; activeLetter=null; collapsedCategories=new Set(); shotCache.clear(); expandedShotPanels.clear();}
